//! The traits a user implements (`ComponentSubscription` via the derive,
//! `Component` by hand) and the type-level dependency list the derive builds.

/// What a component subscribes to. Generated by
/// `#[derive(ComponentSubscription)]` from `#[subscribe(name: Type, ...)]`.
pub trait ComponentSubscription: 'static {
    /// The subscriptions as a type-level tree of tuples (see [`DepList`]),
    /// walked by the runtime. Listing order is the order of `#[subscribe(...)]`.
    type Deps: DepList;
    /// A struct with one named reference per subscription.
    type Input<'a>;
    /// Name the runtime's nested tuple of references.
    fn input<'a>(raw: <Self::Deps as DepList>::Inputs<'a>) -> Self::Input<'a>;
}

/// A node of the dataflow graph.
///
/// # Execution order
///
/// The order in which `update` is called is part of the contract: a
/// depth-first post-order that follows subscription listing order. For a
/// component `C` subscribing to `[D1, .., Dn]` (in `#[subscribe]` order), the
/// updates that happen during `C`'s walk come in `n` blocks followed by `C`
/// itself. Block `i` is `Di` plus everything upstream of `Di` that has not
/// already run in this `run`, itself in this same order. The blocks come in
/// listing order, so a later-listed dependency that is upstream of an earlier
/// one runs inside the earlier block. A component runs exactly once per run,
/// after everything it subscribes to. `Pipeline::order` reports the
/// *construction* order, which is the same order.
pub trait Component: ComponentSubscription + Sized {
    /// Owned configuration passed to `new`. Components without an entry in
    /// [`Configs`](crate::Configs) get `Default::default()`.
    type Config: Default + 'static;
    /// What `update` produces; subscribers receive `&Output`. Outputs of
    /// non-root components are dropped when `run` finishes; the root's output
    /// is returned to the caller of `run`.
    type Output: 'static;

    fn new(config: Self::Config) -> Self;

    /// Invoked once per `Pipeline::run`, after everything it subscribes to.
    fn update(&mut self, input: Self::Input<'_>) -> Self::Output;
}

/// A node of the subscription tree: the type the derive builds for
/// [`ComponentSubscription::Deps`]. User code never writes one.
///
/// Rust has no variadic generics, so every recursive operation in this crate
/// (plan, storage, walk, lookup, cycle check) is a handful of impls, one per
/// node *shape*:
///
/// * `()`: no subscriptions;
/// * a leaf, a plain tuple of 1 to 4 components `(A,)`, `(A, B)`, `(A, B, C)`,
///   `(A, B, C, D)`;
/// * an inner node `(A, B, C, D, K0, K1, K2, K3)` with 4 components and 4 child
///   nodes (unused children are `()`), used for more than 4 subscriptions.
///
/// Listing order is the order of the entries of a node followed by its children
/// left to right. The derive fills nodes left to right and keeps the tree
/// shallow (depth grows with log4 of the number of subscriptions): 12
/// subscriptions are `(A, B, C, D, (E, F, G, H), (I, J, K, L), (), ())`.
pub trait DepList: 'static {
    /// The nested tuple of references `update` is handed, before the derive
    /// names its fields. It has the shape of the node.
    type Inputs<'a>;
}

impl DepList for () {
    type Inputs<'a> = ();
}

macro_rules! dep_list_impl {
    ([$($E:ident)+] [$($K:ident)*]) => {
        impl<$($E: Component,)+ $($K: DepList,)*> DepList for ($($E,)+ $($K,)*) {
            type Inputs<'a> = ($(&'a $E::Output,)+ $($K::Inputs<'a>,)*);
        }
    };
}
dep_list_impl!([A][]);
dep_list_impl!([A B][]);
dep_list_impl!([A B C][]);
dep_list_impl!([A B C D][]);
dep_list_impl!([A B C D][K0 K1 K2 K3]);
